patch:
diff --git a/lib/rules/no-loss-of-precision.js b/lib/rules/no-loss-of-precision.js
index 7fc0240..f9f6654 100644
--- a/lib/rules/no-loss-of-precision.js
+++ b/lib/rules/no-loss-of-precision.js
@@ -183,6 +183,17 @@ module.exports = {
 			return `${normalizedCoefficient}e${magnitude}`;
 		}

+		/**
+		 * Removes trailing zeros from the coefficient of a number in normalized scientific notation
+		 * @param {string} scientificNotation the number in the format returned by `convertNumberToScientificNotation`
+		 * @returns {string} the number with trailing zeros removed from its coefficient
+		 */
+		function removeTrailingZerosFromCoefficient(scientificNotation) {
+			const [coefficient, magnitude] = scientificNotation.split("e");
+
+			return `${removeTrailingZeros(coefficient)}e${magnitude}`;
+		}
+
 		/**
 		 * Checks that the user-intended base ten number equals the actual number after is has been converted to the Number type
 		 * @param {Node} node the node being evaluated
@@ -203,7 +214,10 @@ module.exports = {
 			const normalizedStoredNumber =
 				convertNumberToScientificNotation(storedNumber);

-			return normalizedRawNumber !== normalizedStoredNumber;
+			return (
+				removeTrailingZerosFromCoefficient(normalizedRawNumber) !==
+				removeTrailingZerosFromCoefficient(normalizedStoredNumber)
+			);
 		}

 		/**
